create or replace function public.get_sellertray_customer_receivables(p_tenant_id uuid,p_limit integer default 500)
returns table(order_id uuid,public_order_id text,branch_id uuid,branch_name text,customer_id uuid,customer_name text,customer_phone text,source text,currency text,total_amount numeric,amount_paid numeric,outstanding_amount numeric,created_at timestamptz)
language plpgsql stable security definer set search_path=''
as $$declare v_user_id uuid:=auth.uid();v_limit integer:=greatest(1,least(coalesce(p_limit,500),1000));begin if v_user_id is null then raise exception 'SellerTray authentication required' using errcode='42501';end if;if not public.sellertray_user_has_capability(p_tenant_id,v_user_id,'can_view_reports') then raise exception 'You do not have permission to view customer balances' using errcode='42501';end if;return query select o.id,o.public_order_id,o.branch_id,b.name,o.customer_id,coalesce(c.display_name,c.phone,c.wa_id,'Customer'),c.phone,o.source,o.currency,o.total_amount,o.amount_paid,greatest(o.total_amount-o.amount_paid,0)::numeric,o.created_at from public.orders o join public.branches b on b.tenant_id=o.tenant_id and b.id=o.branch_id join public.customers c on c.tenant_id=o.tenant_id and c.id=o.customer_id where o.tenant_id=p_tenant_id and o.deleted_at is null and o.status='completed' and o.customer_id is not null and o.total_amount>o.amount_paid and public.sellertray_user_can_read_report_branch(p_tenant_id,o.branch_id,v_user_id) order by o.created_at desc,o.id limit v_limit;end$$;
revoke all on function public.get_sellertray_customer_receivables(uuid,integer) from public,anon;grant execute on function public.get_sellertray_customer_receivables(uuid,integer) to authenticated,service_role;

create or replace function public.get_sellertray_sale_return_history(p_tenant_id uuid,p_limit integer default 500)
returns table(return_id uuid,order_id uuid,public_order_id text,branch_id uuid,branch_name text,customer_id uuid,customer_name text,amount numeric,currency text,reason text,created_at timestamptz,items jsonb)
language plpgsql stable security definer set search_path=''
as $$declare v_user_id uuid:=auth.uid();v_limit integer:=greatest(1,least(coalesce(p_limit,500),1000));begin if v_user_id is null then raise exception 'SellerTray authentication required' using errcode='42501';end if;if not public.sellertray_user_has_capability(p_tenant_id,v_user_id,'can_view_reports') then raise exception 'You do not have permission to view return history' using errcode='42501';end if;return query select sr.id,sr.order_id,o.public_order_id,sr.branch_id,b.name,o.customer_id,coalesce(c.display_name,c.phone,c.wa_id,'Walk-in customer'),sr.amount,sr.currency,sr.reason,sr.created_at,coalesce((select jsonb_agg(jsonb_build_object('productName',sri.product_name,'selectedUom',sri.selected_uom,'quantity',sri.quantity,'stockQuantity',sri.stock_quantity,'lineTotal',sri.line_total) order by sri.created_at,sri.id) from public.sale_return_items sri where sri.tenant_id=sr.tenant_id and sri.sale_return_id=sr.id),'[]'::jsonb) from public.sale_returns sr join public.orders o on o.tenant_id=sr.tenant_id and o.id=sr.order_id join public.branches b on b.tenant_id=sr.tenant_id and b.id=sr.branch_id left join public.customers c on c.tenant_id=o.tenant_id and c.id=o.customer_id where sr.tenant_id=p_tenant_id and sr.status='completed' and public.sellertray_user_can_read_report_branch(p_tenant_id,sr.branch_id,v_user_id) order by sr.created_at desc,sr.id limit v_limit;end$$;
revoke all on function public.get_sellertray_sale_return_history(uuid,integer) from public,anon;grant execute on function public.get_sellertray_sale_return_history(uuid,integer) to authenticated,service_role;

create or replace function public.get_sellertray_payment_reconciliation(p_tenant_id uuid,p_limit integer default 300)
returns table(payment_id uuid,order_id uuid,public_order_id text,branch_id uuid,customer_name text,method_type text,provider text,status text,exception_state text,exception_reason text,amount numeric,currency text,provider_reference text,created_at timestamptz)
language plpgsql stable security definer set search_path=''
as $$declare v_user_id uuid:=auth.uid();v_limit integer:=greatest(1,least(coalesce(p_limit,300),1000));begin if v_user_id is null then raise exception 'SellerTray authentication required' using errcode='42501';end if;if not public.sellertray_user_has_capability(p_tenant_id,v_user_id,'can_view_reports') then raise exception 'You do not have permission to review payments' using errcode='42501';end if;return query select p.id,p.order_id,o.public_order_id,o.branch_id,coalesce(c.display_name,c.phone,c.wa_id,'Customer'),p.method_type,p.provider,p.status,p.exception_state,p.exception_reason,p.amount,p.currency,p.provider_reference,p.created_at from public.order_payments p join public.orders o on o.tenant_id=p.tenant_id and o.id=p.order_id left join public.customers c on c.tenant_id=o.tenant_id and c.id=o.customer_id where p.tenant_id=p_tenant_id and o.deleted_at is null and public.sellertray_user_can_read_report_branch(p_tenant_id,o.branch_id,v_user_id) order by case when p.status='pending_verification' or p.status='failed' or p.exception_state<>'none' then 0 else 1 end,p.created_at desc,p.id limit v_limit;end$$;
revoke all on function public.get_sellertray_payment_reconciliation(uuid,integer) from public,anon;grant execute on function public.get_sellertray_payment_reconciliation(uuid,integer) to authenticated,service_role;
